<?php require __DIR__.'/../includes/bootstrap.php';admin_required();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="pedidos-'.date('Y-m-d').'.csv"');$out=fopen('php://output','w');fputcsv($out,['Pedido','Fecha','Cliente','WhatsApp','Subtotal','Delivery','Total','Estado','Dirección']);$q=db()->query('SELECT public_id,created_at,customer_name,whatsapp,subtotal,delivery_cost,total,status,address FROM orders ORDER BY id DESC');foreach($q as $r)fputcsv($out,$r);fclose($out);